-- VSF 63 — La fiche métier VSF (source unique) et les 4 niveaux. Première des 6 migrations du chantier « Formation premium » (63 à 68).
-- Accord de Stéphane : principe des 6 migrations, le 16 novembre 2026. Une migration à la fois, avec sauvegarde et vérification avant.
-- Ce que fait cette migration : elle CRÉE 3 tables neuves et y recopie les données existantes. Elle ne modifie, ne supprime et ne lit AUCUNE table existante,
--   en particulier aucune table de Maurice ni de l'estimation.
--   • vsf_fiches_metiers   : une ligne par fiche (PL, GA, DI), recopiée de site/data/fiches-diag.json (version « 2026-11-10b ») ;
--   • vsf_fiche_situations : une ligne par situation de la fiche (15 au total), avec les repères N1 à N4, preuves, indicateurs, piège du travail réel ;
--   • vsf_form_niveaux     : les 4 niveaux (N1 Comprendre · N2 Faire avec repères · N3 Réaliser seul·e · N4 Maîtriser et transmettre).
-- Clé des situations : (fiche_code, idx) où idx est la position (0 = première) ; la colonne situation_code vaut « fiche:idx » (ex. PL:0) : c'est
--   déjà le code utilisé par vsf_autopositionnements et vsf_objectifs, donc rien n'est à convertir. Le code d'étape de la fiche (c1, c2…) est gardé tel quel
--   dans « etape » : il N'EST PAS unique (la fiche GA a deux « c2 »), ce n'est donc pas une clé.
-- Deux noms par situation : « intitule » (le texte long de la fiche) et « nom » (le nom court validé). Écrans : nom, sinon intitule.
--   Seules les 5 situations de Peintre en lettres ont un nom court validé ; GA et DI n'en ont pas encore (nom vide).
-- Lecture : toute personne connectée (comme la fiche actuelle). Écriture : administrateur seulement. Rien pour le public.
-- Rejouable : relancée, elle n'écrase JAMAIS une ligne déjà présente (on conflict do nothing). Retour arrière : vsf_63_rollback.sql.
begin;

do $$
begin
  if to_regprocedure('public.vsf_est_admin()') is null then
    raise exception 'Fonction vsf_est_admin introuvable. Rien n''est modifié.';
  end if;
end $$;

create table if not exists vsf_fiches_metiers (
  code     text primary key check (code ~ '^[A-Z0-9_-]{1,12}$'),
  nom      text not null,
  type     text not null default 'metier' check (type in ('metier', 'socle')),
  art      boolean not null default false,
  source   text,
  version  text,
  note     text,
  statut   text not null default 'brouillon' check (statut in ('brouillon', 'validee')),
  maj_le   timestamptz not null default now()
);

create table if not exists vsf_fiche_situations (
  fiche_code         text not null references vsf_fiches_metiers(code) on delete cascade,
  idx                smallint not null check (idx between 0 and 19),
  situation_code     text not null check (situation_code = fiche_code || ':' || idx::text),   -- toujours « fiche:idx » (ex. PL:0), comme vsf_autopositionnements
  etape              text,
  intitule           text not null,
  nom                text,
  geste_rare         boolean not null default false,
  cycle              text,
  geste_outils       text,
  exigences          text,
  reperes            jsonb not null default '[]'::jsonb,   -- 4 textes : N1 à N4
  preuves            jsonb not null default '[]'::jsonb,   -- 4 textes : N1 à N4
  indicateurs        text,
  piege_travail_reel text,
  sources_statut     text,
  statut             text,
  maj_le             timestamptz not null default now(),
  primary key (fiche_code, idx),
  unique (situation_code)
);

create table if not exists vsf_form_niveaux (
  niveau       smallint primary key check (niveau between 1 and 4),
  nom          text not null,
  description  text,
  preuve       text
);

alter table vsf_fiches_metiers enable row level security;
alter table vsf_fiche_situations enable row level security;
alter table vsf_form_niveaux enable row level security;
revoke all on vsf_fiches_metiers, vsf_fiche_situations, vsf_form_niveaux from anon, authenticated;
grant select on vsf_fiches_metiers, vsf_fiche_situations, vsf_form_niveaux to authenticated;
grant insert, update, delete on vsf_fiches_metiers, vsf_fiche_situations, vsf_form_niveaux to authenticated;   -- limité par les politiques ci-dessous (administrateur seulement)

drop policy if exists vsf_fiches_metiers_lecture on vsf_fiches_metiers;
create policy vsf_fiches_metiers_lecture on vsf_fiches_metiers for select to authenticated using (true);
drop policy if exists vsf_fiches_metiers_ecriture on vsf_fiches_metiers;
create policy vsf_fiches_metiers_ecriture on vsf_fiches_metiers for all to authenticated using (vsf_est_admin()) with check (vsf_est_admin());

drop policy if exists vsf_fiche_situations_lecture on vsf_fiche_situations;
create policy vsf_fiche_situations_lecture on vsf_fiche_situations for select to authenticated using (true);
drop policy if exists vsf_fiche_situations_ecriture on vsf_fiche_situations;
create policy vsf_fiche_situations_ecriture on vsf_fiche_situations for all to authenticated using (vsf_est_admin()) with check (vsf_est_admin());

drop policy if exists vsf_form_niveaux_lecture on vsf_form_niveaux;
create policy vsf_form_niveaux_lecture on vsf_form_niveaux for select to authenticated using (true);
drop policy if exists vsf_form_niveaux_ecriture on vsf_form_niveaux;
create policy vsf_form_niveaux_ecriture on vsf_form_niveaux for all to authenticated using (vsf_est_admin()) with check (vsf_est_admin());

-- Les 4 niveaux (textes repris tels quels de la page production.html, noms du prompt du 16 nov.)
insert into vsf_form_niveaux (niveau, nom, description, preuve) values
  (1, $t$Comprendre$t$, $t$Reconnaître vocabulaire, outils, supports, règles, risques et critères de base$t$, $t$documentée (quiz réussi)$t$),
  (2, $t$Faire avec repères$t$, $t$Exécuter une tâche simple avec méthode et correction$t$, $t$observée (dépôt corrigé)$t$),
  (3, $t$Réaliser seul·e$t$, $t$Conduire une situation courante avec autonomie croissante$t$, $t$observée (en situation réelle)$t$),
  (4, $t$Maîtriser et transmettre$t$, $t$Traiter le complexe, justifier ses choix et aider autrui à progresser$t$, $t$validée (jury)$t$)
on conflict (niveau) do nothing;

