-- Contrôles (attendu : 3 · 15 · 5 · 4 · oui · oui · oui) -------------------------------------------------------------
select 'fiches' as controle, count(*)::text as resultat from vsf_fiches_metiers
union all select 'situations', count(*)::text from vsf_fiche_situations
union all select 'situations de Peintre en lettres avec nom court (attendu 5)', count(*)::text from vsf_fiche_situations where fiche_code = 'PL' and nom is not null
union all select 'niveaux', count(*)::text from vsf_form_niveaux
union all select 'lecture fermée au public (attendu : oui)', case when not has_table_privilege('anon', 'public.vsf_fiches_metiers', 'select') and not has_table_privilege('anon', 'public.vsf_fiche_situations', 'select') and not has_table_privilege('anon', 'public.vsf_form_niveaux', 'select') then 'oui' else 'NON' end
union all select 'codes de situation compatibles avec vsf_autopositionnements (PL:0 existe)', case when exists (select 1 from vsf_fiche_situations where situation_code = 'PL:0') then 'oui' else 'NON' end
union all select 'écriture réservée à l''administrateur (attendu : oui)', case when (select count(*) from pg_policies where tablename in ('vsf_fiches_metiers', 'vsf_fiche_situations', 'vsf_form_niveaux') and policyname like '%ecriture') = 3 then 'oui' else 'NON' end;
